<?php
requireAdmin();$title='ניהול קהילת המטיילים';$error='';$history=($_GET['view']??'')==='history';$notice=$_SESSION['moderation_notice']??'';unset($_SESSION['moderation_notice']);
if($_SERVER['REQUEST_METHOD']==='POST')try{(in_array($_POST['kind']??'',['settings','appeal'],true)||in_array($_POST['decision']??'',['needs_info','merge','unmerge'],true)?'networkReviewAction':(in_array($_POST['kind']??'',['post','comment','translation'],true)?'networkModerate':'socialModerate'))((string)($_POST['kind']??''),(string)($_POST['id']??''),(string)($_POST['decision']??''),(int)($_POST['revision']??0));$_SESSION['moderation_notice']=['approve'=>'הפרסום אושר בהצלחה.','reject'=>'התוכן נדחה.','block'=>'התוכן הוסתר.','needs_info'=>'בקשת ההשלמה נשלחה.'][$_POST['decision']??'']??'הפעולה נשמרה בהצלחה.';redirect('/KNISA/community/?'.http_build_query(array_intersect_key($_GET,array_flip(['view','type','state','language','city','author','q','page']))+['reviewed'=>1]).'#moderation-status');}catch(DomainException $e){$error=socialT($e->getMessage());}
function socialAdminActionAllowed(string $kind,string $id,string $action): bool {
 if($kind==='trip'){ $trip=socialQuery('SELECT * FROM member_trips WHERE id=?',[$id])->fetch();return $trip&&(in_array($action,['approve','reject'],true)?!empty($trip['pending_plan']):($action==='block'&&$trip['state']!=='blocked'));}
 if($kind==='translation'&&$action==='block')return false;
 if($kind==='member'){$state=socialQuery('SELECT state FROM members WHERE id=?',[$id])->fetchColumn();return $action==='block'?$state==='active':($action==='restore'&&$state==='blocked');}
 $table=['place'=>'member_places','post'=>'network_posts','comment'=>'network_comments','translation'=>'network_submissions'][$kind]??null;if(!$table)return true;
 $state=socialQuery("SELECT state FROM $table WHERE id=?",[$id])->fetchColumn();
 return in_array($action,['approve','reject','needs_info'],true)?$state==='pending':($action==='block'&&in_array($state,['pending','published','approved'],true));
}
function socialAdminActions(string $kind,string $id,int $revision=0): void {echo '<form method="post">'.csrf().'<input type="hidden" name="expected_version" value="'.e(networkReviewVersion($kind,$id)).'">'.'<input type="hidden" name="kind" value="'.e($kind).'"><input type="hidden" name="id" value="'.e($id).'"><input type="hidden" name="revision" value="'.$revision.'">';if(in_array($kind,['place','translation','trip','post','comment'],true))echo '<label>הערה למחבר<input name="moderator_note" maxlength="500"></label>';foreach(($kind==='report'?['resolve'=>'סגירת דיווח']:($kind==='member'?['block'=>'חסימת חשבון','restore'=>'החזרת חשבון']:['approve'=>'אישור פרסום','reject'=>'דחייה','block'=>'הסתרה']+($kind==='place'?['needs_info'=>'בקשת השלמה']:[]))) as $action=>$name)if(socialAdminActionAllowed($kind,$id,$action))echo '<button name="decision" value="'.$action.'">'.$name.'</button>';echo '</form>';}
if(!$history){require ROOT.'/views/admin-review-queue.php';return;}
ob_start();?><div class="social-page"><h1><?=e($title)?></h1><a href="/KNISA/">חזרה לניהול</a><?php if($error):?><p role="alert"><?=e($error)?></p><?php endif?><?php if($notice):?><div id="moderation-status" class="social-card" role="status" tabindex="-1" style="background:#e8f6ef;border:2px solid #00856f"><strong><?=e($notice)?></strong><p data-review-next-message>ממשיכים לפריטים שממתינים לבדיקה.</p></div><?php endif?><nav aria-label="תצוגת בדיקה"><a class="button secondary" href="/KNISA/community/">ממתינים לאישור</a> <a class="button secondary" href="/KNISA/community/?view=history">כל התכנים וההיסטוריה</a></nav><p>בדקו דיוק, זכויות תמונה, פרטיות והתאמה ליעד. אישור פרסום אינו אימות מחיר או שעות עדכניים. פעולות נשמרות ביומן.</p>
<h2>מקומות לבדיקה</h2><?php foreach(socialQuery("SELECT p.*,m.handle FROM member_places p JOIN members m ON m.id=p.owner ".($history?"":"WHERE p.state='pending'")." ORDER BY (p.state='pending') DESC,p.created DESC LIMIT 100") as $r):$p=json_decode($r['document'],true);?><article class="social-card" <?= $r['state']==='pending'?'data-review-pending':'' ?>><h3><?=e($p['title'])?></h3><p>@<?=e($r['handle'])?> · <?=e($r['state'])?> · <?=e($p['city'])?> · <?=e($p['category'])?> · <?=e($p['cost'])?></p><p><?=nl2br(e($p['description']))?></p><dl><?php foreach(['address','hours','price'] as $key):?><dt><?=e($key)?></dt><dd><?=e($p[$key])?></dd><?php endforeach?></dl><?php foreach($p['photos']??array_filter([$p['photo']]) as $photo):?><img src="/community/media/<?=e($photo)?>/" width="400" alt="תמונה לבדיקה"><?php endforeach?><?php require ROOT.'/views/network-place-admin.php';if($r['state']!=='merged')socialAdminActions('place',$r['id']);?></article><?php endforeach?>
<h2>טיולים לבדיקה</h2><?php foreach(socialQuery("SELECT t.*,m.handle FROM member_trips t JOIN members m ON m.id=t.owner WHERE t.pending_plan IS NOT NULL ORDER BY updated LIMIT 100") as $r):$p=json_decode($r['pending_plan'],true);?><article class="social-card" data-review-pending><h3>@<?=e($r['handle'])?> · <?=e($p['city'])?></h3><ol><?php foreach($p['items'] as $x):?><li>יום <?=(int)$x['day']?> · <?=e($x['title'])?> <?=$x['custom']?'(פריט חדש לבדיקה)':''?></li><?php endforeach?></ol><?php foreach($p['photos']??[] as $photo):?><img src="/community/media/<?=e($photo)?>/" width="400" alt="תמונה לבדיקה"><?php endforeach?><?php socialAdminActions('trip',$r['id'],(int)$r['revision']);?></article><?php endforeach?>
<h2>דיווחים פתוחים</h2><?php foreach(socialQuery("SELECT * FROM member_reports WHERE state='open' ORDER BY created LIMIT 100") as $r){echo '<article class="social-card"><p>'.e($r['kind'].' · '.$r['target']).'</p><p>'.e($r['reason']).'</p>';if($r['kind']==='trip'){$tr=socialQuery('SELECT revision FROM member_trips WHERE id=?',[$r['target']])->fetchColumn();echo '<a href="/community/trips/'.e($r['target']).'/">תצוגה</a>';if($tr){socialAdminActions('trip',$r['target'],(int)$tr);}}elseif($r['kind']==='member'){socialAdminActions('member',$r['target']);}elseif(in_array($r['kind'],['place','post','comment'],true)){socialAdminActions($r['kind'],$r['target']);}socialAdminActions('report',(string)$r['id']);echo '</article>';}?>
<?php require ROOT.'/views/network-admin.php';?><h2>חברי קהילה</h2><?php foreach(socialQuery('SELECT id,handle,state FROM members ORDER BY created DESC LIMIT 100') as $r):?><article class="social-card"><p>@<?=e($r['handle'])?> · <?=e($r['state'])?></p><?php socialAdminActions('member',$r['id']);?></article><?php endforeach?>
<script src="/assets/moderation-queue.js?v=2" defer></script></div><?php $content=ob_get_clean();require ROOT.'/views/layout.php';
